Method.Implementation:
$$$TRACE("Inside  Method OnGetConnections")
For j=0:1:numIn-1{
If pItem.GetModifiedSetting("ShMedicare837TargetConfigName",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue_"-"_j,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
}

    set retCode = resp.retCode
	set retDesc =resp.retDesc
	set isSuccess=resp.isSuccess
	if (isSuccess="N"){
		set process1.errMsg = process1.errMsg_retDesc
		set process1.numErrBatchCounts =  process1.numErrBatchCounts +1
	}else{
		set process1.numSuccessBatchCounts =  process1.numSuccessBatchCounts +1
	}
	$$$TRACE("process1.numSuccessBatchCounts: "_process1.numSuccessBatchCounts)
	$$$TRACE("process1.numErrBatchCounts"_process1.numErrBatchCounts)
	$$$TRACE("process1.errMsg:"_process1.errMsg)

	quit $$$OK
